 public sealed class CombatAdControllerTests {
  sealed class Wire:IRunApiHttpTransport {public readonly List<RunApiHttpRequest> Calls=new();public Func<RunApiHttpRequest,Task<RunApiHttpResponse>> Reply;public readonly AdStartTestProtocol Protocol=new();public Task<RunApiHttpResponse> SendAsync(RunApiHttpRequest q){Calls.Add(q);return Protocol.Send(q,Reply);}}
  sealed class Journal:IAccountActionJournal,IAccountAdActionJournal {public PendingAccountAction Row;public bool Fail;public PendingAccountAction Read(string a)=>Row?.Account==a?Row:null;public bool Save(PendingAccountAction a){if(Fail||Row!=null)return false;Row=a;return true;}public bool Remove(PendingAccountAction a){if(Fail||Row!=a)return false;Row=null;return true;}public bool ReplaceAd(PendingAccountAction a,PendingAccountAction b){if(Fail||Row!=a)return false;Row=b;return true;}}
  sealed class Ad:IRewardAdPresentation {public bool Available=>true;public int Shows;public Task ShowAsync(string u,string c,string a){Shows++;return Task.CompletedTask;}}
  sealed class UnavailableJournal:IAccountActionJournal {public PendingAccountAction Read(string a)=>throw new InvalidOperationException("TEST storage unavailable");public bool Save(PendingAccountAction a)=>false;public bool Remove(PendingAccountAction a)=>false;}
  [Test] public async Task CompositionHandlesUnavailableStorageWithoutSendingOrThrowing(){var w=new Wire();var s=Session();using var account=new AccountScreenRuntime(w,new UnavailableJournal(),()=>s,()=>1);await account.RunCombatAdAsync("run_test","read");Assert.That(w.Calls,Is.Empty);Assert.That(account.CombatAds.Notice,Does.Contain("보관함"));}
  // Memory-only storage adapter exercises the production journal format and CAS;
  // it is deliberately not evidence of device keystore cryptography.
  sealed class Storage:IAndroidKeystoreNativeStoragePort {
   AndroidKeystoreEncryptedTokenPayload saved;public bool IsAndroidRuntime=>true;public bool IsKeystoreAvailable=>true;public string ProviderName=>"TEST_ONLY";public bool UsedPlayerPrefsFallback=>false;
   public AndroidKeystoreEncryptedTokenPayload Encrypt(string s)=>new(Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(s)),"TEST_IV");public string Decrypt(AndroidKeystoreEncryptedTokenPayload p)=>System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(p.CipherTextBase64));public bool Save(AndroidKeystoreEncryptedTokenPayload p){saved=p;return true;}public AndroidKeystoreEncryptedTokenPayload Load()=>saved;public bool Clear(){saved=null;return true;}
  }
  [Test] public void ProductionJournalPreservesCombatStateAndRejectsCrossPlacement(){var port=new Storage();var journal=new AccountActionJournal(port);var initial=new PendingAccountAction("a","combat-ad-create","run_test",0,"create_key","{\"runId\":\"run_test\",\"rewardPreviewId\":\"preview_test\"}");Assert.That(journal.Save(initial),Is.True);var intent=new PendingAccountAction("a","combat-ad-intent","run_test",0,"create_key",Sample().ToString());Assert.That(journal.ReplaceAd(initial,intent),Is.True);var restored=new AccountActionJournal(port).Read("a");Assert.That(restored.Payload,Is.EqualTo(intent.Payload));var other=new PendingAccountAction("a","ad-create","",0,"other");Assert.That(journal.ReplaceAd(restored,other),Is.False);var wrong=Sample();wrong["customData"]="changed";Assert.Throws<FormatException>(()=>journal.ReplaceAd(restored,new PendingAccountAction("a","combat-ad-presented","run_test",0,"create_key",wrong.ToString())));Assert.That(journal.Read("a").Payload,Is.EqualTo(intent.Payload));}
  static GameApiAuthSessionSnapshot Session()=>new("a","ACTIVE",new GameApiAccessToken("lst1.fixture"),DateTime.UtcNow.AddMinutes(5),new GameApiRefreshToken("fixture"),DateTime.UtcNow.AddMinutes(10));
  public static JObject Sample(string status="AD_PENDING")=>new JObject{["accepted"]=true,["intentId"]="ad_test",["runId"]="run_test",["rewardPreviewId"]="preview_test",["status"]=status,["canSpin"]=status=="AD_VERIFIED"||status=="RESULT_FIXED",["canClaimBasic"]=status!="CLAIMED"&&status!="REWARD_CONSUMED",["createdAt"]=1000,["expiresAt"]=2000,["callbackDeadline"]=3000,["serverNow"]=1500,["userId"]="binding",["customData"]="challenge",["adUnit"]="TEST_ONLY",["policyVersion"]="test-v1",["probabilities"]=JArray.Parse("[{\"multiplier\":2,\"weightBps\":6000},{\"multiplier\":3,\"weightBps\":3000},{\"multiplier\":4,\"weightBps\":1000}]"),["eligibleBaseRewardLines"]=JArray.Parse("[{\"kind\":\"CURRENCY\",\"id\":\"cur_credits\",\"quantity\":240,\"source\":\"RUN_CLEAR\"}]"),["excludedBaseRewardLines"]=new JArray(),["result"]=status=="CLAIMED"?Result():null};
  public static JObject Result()=>new JObject{["accepted"]=true,["intentId"]="ad_test",["runId"]="run_test",["rewardPreviewId"]="preview_test",["status"]="CLAIMED",["multiplier"]=2,["policyVersion"]="test-v1",["rewardClaimId"]="claim_test",["serverClaimedAt"]="2026-09-17T00:00:00.000Z",["rewardLines"]=JArray.Parse("[{\"kind\":\"CURRENCY\",\"id\":\"cur_credits\",\"quantity\":480,\"source\":\"RUN_CLEAR\",\"balanceAfter\":480}]")};
  static Task<RunApiHttpResponse> Reply(string status)=>Task.FromResult(RunApiHttpResponse.Success(200,Sample(status).ToString()));
  [Test] public void ContractRejectsWrongRunAndFalseSpin(){var o=Sample();o["canSpin"]=true;Assert.Throws<FormatException>(()=>CombatAdIntent.Parse(o.ToString(),"run_test","preview_test"));Assert.Throws<FormatException>(()=>CombatAdIntent.Parse(Sample().ToString(),"other","preview_test"));}
  [Test] public void ResultRejectsChangedReceiptAndPreservesExcludedRewards(){var a=CombatAdIntent.Parse(Sample("CLAIMED").ToString(),"run_test","preview_test");var changed=Sample("CLAIMED");changed["result"]["rewardLines"][0]["quantity"]=999;var b=CombatAdIntent.Parse(changed.ToString(),"run_test","preview_test");Assert.Throws<FormatException>(()=>b.RequireSame(a));Assert.That(a.Result["rewardLines"][0]["quantity"].Value<int>(),Is.EqualTo(480));}
  [Test] public async Task DefinitivePolicyFailureLeavesBasicPathUnblocked(){var w=new Wire{Reply=q=>Task.FromResult(RunApiHttpResponse.Success(503,"{\"accepted\":false,\"errorCode\":\"ad_reward_policy_unconfigured\"}"))};var j=new Journal();var s=Session();var ad=new Ad();using var c=new CombatAdController(w,j,()=>s,()=>1,()=>ad,()=>Task.FromResult(true));await c.BeginAsync("run_test","preview_test");Assert.That(j.Row,Is.Null);Assert.That(ad.Shows,Is.Zero);}
  [Test] public async Task BasicClaimWinningNeverCallsSpin(){var w=new Wire{Reply=q=>Reply("REWARD_CONSUMED")};var j=new Journal{Row=new PendingAccountAction("a","combat-ad-presented","run_test",0,"old",Sample().ToString())};var s=Session();using var c=new CombatAdController(w,j,()=>s,()=>1,()=>null);await c.SpinAsync("run_test","preview_test");Assert.That(w.Calls.All(q=>q.Method=="GET"),Is.True);Assert.That(c.Intent.Status,Is.EqualTo("REWARD_CONSUMED"));c.Acknowledge();Assert.That(j.Row,Is.Null);}
  [Test] public async Task UncertainCreationRestoresKeyWithoutAutomaticAd(){var w=new Wire{Reply=q=>Task.FromResult(RunApiHttpResponse.NetworkError("lost"))};w.Protocol.FreshAdvertising=true;var j=new Journal();var s=Session();var ad=new Ad();using(var c=new CombatAdController(w,j,()=>s,()=>1,()=>ad,()=>Task.FromResult(true))){await c.BeginAsync("run_test","preview_test");}var key=j.Row.Key;w.Reply=q=>Reply("AD_PENDING");using(var c=new CombatAdController(w,j,()=>s,()=>1,()=>ad,()=>Task.FromResult(true))){await c.RefreshAsync("run_test","preview_test");Assert.That(c.CanPresent("run_test"),Is.True);Assert.That(j.Row.Key,Is.EqualTo(key));Assert.That(ad.Shows,Is.Zero);await c.BeginAsync("run_test","preview_test");Assert.That(ad.Shows,Is.EqualTo(1));}}
  [Test] public void NativeViewBindsOnceConfirmsBasicAndUnbinds(){
   var root=new UnityEngine.GameObject("CombatAdViewQA",typeof(UnityEngine.RectTransform),typeof(UnityEngine.Canvas));((UnityEngine.RectTransform)root.transform).sizeDelta=new UnityEngine.Vector2(720,1280);
   try{
    var font=UnityEditor.AssetDatabase.LoadAssetAtPath<TMPro.TMP_FontAsset>("Assets/_LASTRAIL/UI/StartupResources/BootstrapFont.asset");var view=CombatAdView.Create(root.transform,font);view.transform.localScale=UnityEngine.Vector3.one*(720f/941);int main=0,basic=0;view.Bind(()=>main++,()=>{},()=>basic++,()=>{});view.Bind(()=>main++,()=>{},()=>basic++,()=>{});
    view.Render(CombatAdIntent.Parse(Sample("AD_VERIFIED").ToString(),"run_test","preview_test"),"서버 확인 완료",false,true,true,true);
    var buttons=root.GetComponentsInChildren<UnityEngine.UI.Button>();
    var basicCaption=buttons.Single(b=>b.name=="CombatAdBasic").GetComponentInChildren<TMPro.TMP_Text>();basicCaption.ForceMeshUpdate();
    Assert.That(basicCaption.isTextOverflowing,Is.False,"Basic reward action must fit its secondary button");Assert.That(basicCaption.textInfo.lineCount,Is.EqualTo(1));
    buttons.Single(b=>b.name=="CombatAdMain").onClick.Invoke();Assert.That(main,Is.EqualTo(1));
    var basicButton=buttons.Single(b=>b.name=="CombatAdBasic");basicButton.onClick.Invoke();Assert.That(basic,Is.Zero);basicButton.onClick.Invoke();Assert.That(basic,Is.EqualTo(1));
    Capture(root,"combat-roulette-verified.png");view.Render(CombatAdIntent.Parse(Sample("CLAIMED").ToString(),"run_test","preview_test"),"지급 완료",false,false,true,false);Capture(root,"combat-roulette-claimed.png");
    Assert.That(root.GetComponentsInChildren<UnityEngine.UI.Button>().Select(b=>b.name),Is.EqualTo(new[]{"CombatAdMain"}));
    var background=root.GetComponentsInChildren<UnityEngine.UI.RawImage>().Single(g=>g.name=="RouletteRoom");Assert.That(background.rectTransform.rect.height,Is.LessThan(1500));Assert.That(root.GetComponentsInChildren<TMPro.TMP_Text>().Any(t=>t.text.Contains("전투 보상 룰렛")||t.text.Contains("수령 완료 · 확정 보상")||t.text.Contains("60%")),Is.False);
    foreach(var graphic in root.GetComponentsInChildren<UnityEngine.UI.RawImage>()){if(graphic.GetType()==typeof(UnityEngine.UI.RawImage))Assert.That(graphic.texture,Is.Not.Null);Assert.That(graphic.raycastTarget,Is.False);}
    view.Unbind();buttons.Single(b=>b.name=="CombatAdMain").onClick.Invoke();Assert.That(main,Is.EqualTo(1));
   }finally{UnityEngine.Object.DestroyImmediate(root);}
  }
  static void Capture(UnityEngine.GameObject root,string name)=>typeof(AccountScreenIntegrationTests).GetMethod("Capture",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{root,name});
