  }
  [Test] public async Task CommonRecoveryAndVictoryEntryUseStoredRunAndLatestBasicPermission(){
   const string folder="D:/Project/LASTRAIL/unity-project/QA/Unity1Artifacts/Reports/Server2-NoncombatCases-20260914/";
   var life=GameApiJson.ReadObject(System.IO.File.ReadAllText(folder+"result-lost-finish-restored.json"));life["runStatus"]="COMPLETED";life["finish"]["outcome"]="VICTORY";
   string run=(string)life["runId"],preview=(string)life["reward"]["rewardPreviewId"];
   var response=Sample("EXPIRED");response["runId"]=run;response["rewardPreviewId"]=preview;response["canClaimBasic"]=false;
   var pending=Sample();pending["runId"]=run;pending["rewardPreviewId"]=preview;
   var j=new Journal{Row=new PendingAccountAction("a","combat-ad-presented",run,0,"saved_key",pending.ToString())};var w=new Wire{Reply=q=>Task.FromResult(q.EndpointPath.Contains("ad-intents")?RunApiHttpResponse.Success(200,response.ToString()):q.EndpointPath.EndsWith("/lifecycle")?RunApiHttpResponse.Success(200,life.ToString()):RunApiHttpResponse.Success(200,System.IO.File.ReadAllText(folder+"result-preview.json")))};
   var s=Session();using var account=new AccountScreenRuntime(w,j,()=>s,()=>1);using var runs=new DurableRunClient(new GameApiAuthenticatedHttpTransport(w),new EmptyRuns(),()=>s,()=>1);account.BindRunRecovery(runs);
   await account.ReadRunResultsAsync(run);Assert.That(account.CanClaimRunReward(run),Is.True);
   await account.RetryPendingAsync();Assert.That(account.CombatAds.Intent.Status,Is.EqualTo("EXPIRED"));Assert.That(account.CanClaimRunReward(run),Is.False);Assert.That(w.Calls.Any(q=>q.EndpointPath.EndsWith("/ad-intents/ad_test")),Is.True);Assert.That(w.Calls.All(q=>q.Method=="GET"),Is.True);
   var root=new UnityEngine.GameObject("CombatVictoryIntegrationQA",typeof(UnityEngine.RectTransform),typeof(UnityEngine.Canvas));((UnityEngine.RectTransform)root.transform).sizeDelta=new UnityEngine.Vector2(720,1280);var safe=new UnityEngine.GameObject("SafeArea",typeof(UnityEngine.RectTransform));safe.transform.SetParent(root.transform,false);var rect=(UnityEngine.RectTransform)safe.transform;rect.anchorMin=UnityEngine.Vector2.zero;rect.anchorMax=UnityEngine.Vector2.one;rect.sizeDelta=UnityEngine.Vector2.zero;
   try{
    var font=UnityEditor.AssetDatabase.LoadAssetAtPath<TMPro.TMP_FontAsset>("Assets/_LASTRAIL/UI/StartupResources/BootstrapFont.asset");var deck=LobbyCommandDeck.Attach(root,font,"TEST ONLY",0,new MissionShellMissionRowState[0],null,null);deck.BindAccount(account);deck.OpenRunLifecycle(run);Capture(root,"combat-victory-entry.png");
    var entry=root.GetComponentsInChildren<UnityEngine.UI.Button>().Single(b=>b.name=="VictoryAd");Assert.That(entry.interactable,Is.True);entry.onClick.Invoke();Assert.That(root.GetComponentInChildren<CombatAdView>(),Is.Not.Null);Assert.That(root.GetComponentsInChildren<UnityEngine.UI.Button>().Single(b=>b.name=="CombatAdBasic").interactable,Is.False);Capture(root,"combat-roulette-expired.png");deck.CloseDialog();Assert.That(root.GetComponentInChildren<CombatAdView>(),Is.Null);
   }finally{UnityEngine.Object.DestroyImmediate(root);}
   account.CombatAds.Acknowledge();Assert.That(j.Row,Is.Null);Assert.That(account.CanClaimRunReward(run),Is.False);
   await account.CombatAds.RefreshAsync(run,preview);Assert.That(account.CanClaimRunReward(run),Is.False);
  }
  [Test] public async Task ProviderCompletionDoesNotAuthorizeSpinOrAutomaticallyReplay(){var w=new Wire{Reply=q=>Reply("AD_PENDING")};w.Protocol.FreshAdvertising=true;var j=new Journal();var s=Session();var ad=new Ad();using var c=new CombatAdController(w,j,()=>s,()=>1,()=>ad,()=>Task.FromResult(true));await c.BeginAsync("run_test","preview_test");await c.SpinAsync("run_test","preview_test");await c.RefreshAsync("run_test","preview_test");Assert.That(ad.Shows,Is.EqualTo(1));Assert.That(w.Calls.Any(q=>q.EndpointPath.EndsWith("/spin")),Is.False);Assert.That(c.Intent.CanSpin,Is.False);}
  [Test] public async Task LostSpinRetainsKeyAcrossControllerRestart(){var w=new Wire();var j=new Journal();var s=Session();var ad=new Ad();int spins=0;w.Reply=q=>q.EndpointPath.EndsWith("/spin")?(++spins==1?Task.FromResult(RunApiHttpResponse.NetworkError("lost")):Task.FromResult(RunApiHttpResponse.Success(200,Result().ToString()))):Reply("RESULT_FIXED");using(var c=new CombatAdController(w,j,()=>s,()=>1,()=>ad,()=>Task.FromResult(true))){await c.BeginAsync("run_test","preview_test");await c.SpinAsync("run_test","preview_test");}using(var c=new CombatAdController(w,j,()=>s,()=>1,()=>null)){await c.RefreshAsync("run_test","preview_test");await c.SpinAsync("run_test","preview_test");Assert.That(c.Intent.Status,Is.EqualTo("CLAIMED"));}Assert.That(w.Calls.Where(q=>q.EndpointPath.EndsWith("/spin")).Select(q=>q.Headers.Single(h=>h.Name=="Idempotency-Key").Value).Distinct().Count(),Is.EqualTo(1));Assert.That(ad.Shows,Is.Zero);}
  [Test] public async Task StorageFailureAndMissingProviderSendNothing(){var w=new Wire();var j=new Journal{Fail=true};var s=Session();using var c=new CombatAdController(w,j,()=>s,()=>1,()=>new Ad(),()=>Task.FromResult(true));await c.BeginAsync("run_test","preview_test");Assert.That(w.Calls,Is.Empty);using var other=new CombatAdController(w,new Journal(),()=>s,()=>1,()=>null);await other.BeginAsync("run_test","preview_test");Assert.That(w.Calls,Is.Empty);}
  [Test] public async Task AccountChangeDropsLateResponse(){var gate=new TaskCompletionSource<RunApiHttpResponse>();var w=new Wire{Reply=q=>gate.Task};var j=new Journal();var s=Session();long generation=1;using var c=new CombatAdController(w,j,()=>s,()=>generation,()=>new Ad(),()=>Task.FromResult(true));var task=c.BeginAsync("run_test","preview_test");generation++;gate.SetResult(RunApiHttpResponse.Success(200,Sample().ToString()));await task;Assert.That(c.Intent,Is.Null);Assert.That(j.Row.Kind,Is.EqualTo("combat-ad-create"));}
